use super::consts::ABSORPTION_LAYER_THICKNESS;
use super::consts::AIR_DENSITY;
use super::consts::flow_resistivity_for_alpha;
use super::resolved_boundary::ResolvedBoundary;
use super::types::ResolvedBoundaries;
use super::types::boundary_for_room_point;
use num_complex::Complex64;
use sonium_bem::materials::{AmbientMedium, PorousLayer, PorousModel};
use sonium_xem::{PorousModelConfig, RoomSimulation};

pub(super) fn resolve_surface(
    config: &sonium_xem::SurfaceConfig,
    sim_medium: AmbientMedium,
) -> anyhow::Result<ResolvedBoundary> {
    use sonium_xem::SurfaceConfig;
    sim_medium.validate()?;
    Ok(match config {
        SurfaceConfig::Rigid => ResolvedBoundary::Rigid,
        SurfaceConfig::Absorption { coefficient } => {
            anyhow::ensure!(
                coefficient.is_finite() && (0.0..=1.0).contains(coefficient),
                "absorption coefficient must be finite and between zero and one"
            );
            // Render a single Sabine-style absorption coefficient as a
            // frequency-dependent complex admittance via an equivalent 25 mm
            // Miki porous layer back-fit at 500 Hz. This captures the LF
            // mass-loading and phase behavior real treated surfaces exhibit,
            // instead of the unphysical real-Z, flat-α assumption.
            let alpha = coefficient.clamp(0.0, 0.999);
            if alpha <= 1e-6 {
                return Ok(ResolvedBoundary::Rigid);
            }
            let sigma = flow_resistivity_for_alpha(alpha, sim_medium)?;
            let layer = PorousLayer {
                model: PorousModel::Miki,
                thickness: ABSORPTION_LAYER_THICKNESS,
                flow_resistivity: sigma,
                air_gap: 0.0,
            };
            ResolvedBoundary::PorousLayer {
                layer,
                medium: sim_medium,
            }
        }
        SurfaceConfig::Impedance { real, imag } => {
            anyhow::ensure!(
                real.is_finite() && imag.is_finite(),
                "surface impedance must be finite"
            );
            let z = Complex64::new(*real, *imag);
            anyhow::ensure!(
                z.norm() > 0.0,
                "surface impedance must be nonzero (pressure-release needs an explicit admittance model)"
            );
            ResolvedBoundary::Impedance {
                z,
                rho_c: sim_medium.characteristic_impedance(),
            }
        }
        SurfaceConfig::Admittance { real, imag } => {
            anyhow::ensure!(
                real.is_finite() && imag.is_finite(),
                "surface admittance must be finite"
            );
            ResolvedBoundary::Admittance(Complex64::new(*real, *imag))
        }
        SurfaceConfig::PorousLayer {
            model,
            thickness,
            flow_resistivity,
            air_gap,
            ambient,
        } => {
            let layer = PorousLayer {
                model: match model {
                    PorousModelConfig::DelanyBazley => PorousModel::DelanyBazley,
                    PorousModelConfig::Miki => PorousModel::Miki,
                },
                thickness: *thickness,
                flow_resistivity: *flow_resistivity,
                air_gap: air_gap.unwrap_or(0.0),
            };
            layer.validate().map_err(anyhow::Error::msg)?;
            ResolvedBoundary::PorousLayer {
                layer,
                medium: AmbientMedium::try_new(ambient.density, ambient.speed_of_sound)?,
            }
        }
    })
}

pub(super) fn resolve_boundaries(
    simulation: &RoomSimulation,
) -> anyhow::Result<ResolvedBoundaries> {
    let medium = AmbientMedium::try_new(AIR_DENSITY, simulation.speed_of_sound)?;
    let b = &simulation.boundaries;
    let walls = resolve_surface(&b.walls, medium)?;
    Ok(ResolvedBoundaries {
        walls: walls.clone(),
        floor: resolve_surface(&b.floor, medium)?,
        ceiling: resolve_surface(&b.ceiling, medium)?,
        front: b
            .front_wall
            .as_ref()
            .map(|s| resolve_surface(s, medium))
            .transpose()?
            .unwrap_or_else(|| walls.clone()),
        back: b
            .back_wall
            .as_ref()
            .map(|s| resolve_surface(s, medium))
            .transpose()?
            .unwrap_or_else(|| walls.clone()),
        left: b
            .left_wall
            .as_ref()
            .map(|s| resolve_surface(s, medium))
            .transpose()?
            .unwrap_or_else(|| walls.clone()),
        right: b
            .right_wall
            .as_ref()
            .map(|s| resolve_surface(s, medium))
            .transpose()?
            .unwrap_or_else(|| walls.clone()),
    })
}

/// Compute per-element normalized admittance (β = ρc / Zs) for the TBEM room
/// mesh using the same resolved boundary material model as the FEM path.
#[deprecated(note = "panics on invalid input; use try_tbem_element_admittance")]
pub fn tbem_element_admittance(
    simulation: &RoomSimulation,
    mesh: &sonium_xem::RoomMesh,
    frequency: f64,
) -> Vec<Complex64> {
    try_tbem_element_admittance(simulation, mesh, frequency)
        .expect("invalid room material admittance")
}

/// Checked material evaluation for externally supplied room configurations.
pub fn try_tbem_element_admittance(
    simulation: &RoomSimulation,
    mesh: &sonium_xem::RoomMesh,
    frequency: f64,
) -> anyhow::Result<Vec<Complex64>> {
    anyhow::ensure!(
        frequency.is_finite() && frequency > 0.0,
        "material frequency must be finite and positive"
    );
    let boundaries = resolve_boundaries(simulation)?;
    (0..mesh.elements.len())
        .map(|element_idx| {
            let centroid = mesh.element_centroid(element_idx);
            boundary_for_room_point(&simulation.room, &boundaries, centroid)
                .normalized_admittance(frequency)
        })
        .collect()
}
